include AsmInc_MSVC++_x64.inc

	SrcPt		equ rdx
	DstPt		equ rcx
	SzByt		equ r8


_data segment read write align( 16 ) 'data'

	align		16											; 16字节对齐。因为后续2个变量只有16个字节。
	g_CpuIsSuptEnhncFastStrRepMovsbStosb	dq	0			; Cpu是否支持增强的快速字符串Rep Movsb/Stosb指令。
	g_MemCpyFuncPt	dq	SetMemCpyFuncPt						; 声明MemCpy函数的指针。

_data ends


_code segment read execute shared align( 64 ) 'code'

	align		64											; 64字节对齐。
SetMemCpyFuncPt:

	push		rax
	push		rbx
	push		rcx
	push		rdx

	mov			eax, 7
	mov			ecx, 0
	cpuid
	bt			ebx, 9
	jnc			CpuIsSuptEnhncFastStrRepMovsbStosbOut
	mov			g_CpuIsSuptEnhncFastStrRepMovsbStosb, 1
	CpuIsSuptEnhncFastStrRepMovsbStosbOut:

	mov			eax, 1
	cpuid
	bt			ecx, 28
	jnc			SetMemCpySse2
	SetMemCpyAvx:
	mov			rax, offset MemCpyAvx
	mov			g_MemCpyFuncPt, rax
	jmp			SetMemCpyFuncPtOut
	SetMemCpySse2:
	mov			rax, offset MemCpySse2
	mov			g_MemCpyFuncPt, rax
	jmp			SetMemCpyFuncPtOut

	SetMemCpyFuncPtOut:
	pop			rdx
	pop			rcx
	pop			rbx
	pop			rax
	jmp			g_MemCpyFuncPt


	align		64											; 64字节对齐。
public memcpy
memcpy:
public memmove
memmove:
public MemCpy
MemCpy:

	jmp			g_MemCpyFuncPt								; 在MemCpy函数里跳转到函数指针，比直接调用函数指针要快。

	; align		64											; 64字节对齐。这里不进行字节对齐，因为字节对齐会增加无效指令导致执行变慢。
public MemCpyAvx
MemCpyAvx:

	mov			rax, DstPt									; 设置返回值rax为目的地址。

	test		SzByt, -128									; 逻辑与比较SzByt和-128。
	jz			MemCpyAvxSUDUTabJmp							; 如果逻辑与比较结果为0，就表示SzByt无符号小于128字节，不需要进行目的地址32字节对齐，进行Avx指令的源始地址未对齐目的地址未对齐复制，因为小于128字节做目的地址32字节对齐反而慢些，大于等于128字节做目的地址32字节对齐才会快些，且如果一批大于192字节要入栈了。
															; 如果逻辑与比较结果不为0，就表示SzByt无符号大于等于128字节，就需要进行目的地址32字节对齐。

	cmp			DstPt, SrcPt								; 比较DstPt和SrcPt，也就是目的地址和源始地址。
	jbe			MemCpyAvxUp									; 如果DstPt无符号小于等于SrcPt，也就是目的地址小于等于源始地址，表示缓冲区没有重叠，就进行Avx指令的从低到高地址复制。
	lea			r9, [ SrcPt + SzByt ]						; 设置r9为SrcPt+SzByt，也就是源始地址+复制大小。
	cmp			DstPt, r9									; 比较DstPt和r9，也就是目的地址和源始地址+复制大小。
	jb			MemCpyAvxDown								; 如果DstPt无符号小于r9，也就是目的地址小于源始地址+复制大小，表示缓冲区有重叠，就进行Avx指令的从高到低地址复制。
															; 如果DstPt无符号大于等于r9，也就是目的地址大于等于源始地址+复制大小，表示缓冲区没有重叠，就进行Avx指令的从低到高地址复制。

	MemCpyAvxUp:											; Avx指令的从低到高地址复制。
	test		SzByt, -1048576								; 逻辑与比较SzByt和-1048576。
	jnz			MemCpyAvxUpDstAlign							; 如果SzByt无符号大于等于1048576，就进行Avx指令的从低到高地址的目的地址32字节对齐复制，以便使用无缓大段复制。
	test		SzByt, -16384								; 逻辑与比较SzByt和-16384。
	jz			MemCpyAvxUpDstAlign							; 如果SzByt无符号小于16384，就进行Avx指令的从低到高地址的目的地址32字节对齐复制。
															; 如果SzByt无符号大于等于16384，就考虑用rep movsb指令复制。
	mov			r9, SrcPt
	sub			r9, DstPt
	test		r9, -64										; 逻辑与比较r9和-64。
	jz			MemCpyAvxUpDstAlign							; 如果SrcPt减DstPt无符号小于64，表示目的地址在源始地址的前0~63字节，此时用增强的快速字符串Rep Movsb/Stosb指令也会非常慢，就进行Avx指令的从低到高地址的目的地址32字节对齐复制。
	bt			g_CpuIsSuptEnhncFastStrRepMovsbStosb, 0
	jnc			MemCpyAvxUpDstAlign							; 如果CPU不支持增强的快速字符串Rep Movsb/Stosb指令，就进行Avx指令的从低到高地址的目的地址32字节对齐复制。
															; 如果CPU支持增强的快速字符串Rep Movsb/Stosb指令，且SzByt大于等于16384，就用rep movsb指令复制，大部分情况下这样快些。

	push		rsi
	push		rdi
	mov			rsi, SrcPt									; 设置rsi为SrcPt，也就是源始地址。
	mov			rdi, DstPt									; 设置rdi为DstPt，也就是目的地址。
	mov			rcx, SzByt									; 设置rcx为SzByt，也就是复制大小。
	rep movsb
	pop			rdi
	pop			rsi
	ret

	MemCpyAvxUpDstAlign:									; Avx指令的从低到高地址的目的地址32字节对齐复制。
	mov			r9, DstPt									; 设置r9为DstPt，也就是目的地址。
	and			r9, 31										; 设置r9为r9逻辑与31，也就是r9低5位。
	jz			MemCpyAvxUpDstAlignOut						; 如果r9低5位为0，表示目的地址已32字节对齐的，就跳转到开始复制。
															; 如果r9低5位不为0，表示目的地址未32字节对齐的，就进行Avx指令的从低到高地址的目的地址32字节对齐复制，因为非字节对齐的读比非字节对齐的写要快。

	MemCpyAvxUpDstAlignTabJmp:								; Avx指令的从低到高地址的目的地址32字节对齐复制的跳转表的跳转。
	TabJmp		MemCpyAvxUpDstAlignTab, r9*8, r11			; 32-r9就是进行目的地址32字节对齐需要复制的长度。
	; Avx指令的从低到高地址的目的地址32字节对齐复制的跳转表。
	MemCpyAvxUpDstAlignTab	dq	MemCpyAvxUpDstAlign0, MemCpyAvxUpDstAlign31, MemCpyAvxUpDstAlign30, MemCpyAvxUpDstAlign29, MemCpyAvxUpDstAlign28, MemCpyAvxUpDstAlign27, MemCpyAvxUpDstAlign26, MemCpyAvxUpDstAlign25, MemCpyAvxUpDstAlign24, MemCpyAvxUpDstAlign23, MemCpyAvxUpDstAlign22, MemCpyAvxUpDstAlign21, MemCpyAvxUpDstAlign20, MemCpyAvxUpDstAlign19, MemCpyAvxUpDstAlign18, MemCpyAvxUpDstAlign17
							dq	MemCpyAvxUpDstAlign16, MemCpyAvxUpDstAlign15, MemCpyAvxUpDstAlign14, MemCpyAvxUpDstAlign13, MemCpyAvxUpDstAlign12, MemCpyAvxUpDstAlign11, MemCpyAvxUpDstAlign10, MemCpyAvxUpDstAlign9, MemCpyAvxUpDstAlign8, MemCpyAvxUpDstAlign7, MemCpyAvxUpDstAlign6, MemCpyAvxUpDstAlign5, MemCpyAvxUpDstAlign4, MemCpyAvxUpDstAlign3, MemCpyAvxUpDstAlign2, MemCpyAvxUpDstAlign1
	MemCpyAvxUpDstAlign0:
	jmp			MemCpyAvxUpDstAlignOut
	MemCpyAvxUpDstAlign1:
	mov			r9b, byte ptr [ SrcPt + 0 ]
	mov			byte ptr [ DstPt + 0 ], r9b
	inc			SrcPt
	inc			DstPt
	dec			SzByt
	jmp			MemCpyAvxUpDstAlignOut
	MemCpyAvxUpDstAlign2:
	mov			r9w, word ptr [ SrcPt + 0 ]
	mov			word ptr [ DstPt + 0 ], r9w
	add			SrcPt, 2
	add			DstPt, 2
	sub			SzByt, 2
	jmp			MemCpyAvxUpDstAlignOut
	MemCpyAvxUpDstAlign3:
	mov			r9b, byte ptr [ SrcPt + 0 ]
	mov			byte ptr [ DstPt + 0 ], r9b
	mov			r9w, word ptr [ SrcPt + 1 ]
	mov			word ptr [ DstPt + 1 ], r9w
	add			SrcPt, 3
	add			DstPt, 3
	sub			SzByt, 3
	jmp			MemCpyAvxUpDstAlignOut
	MemCpyAvxUpDstAlign4:
	movd		xmm0, dword ptr [ SrcPt + 0 ]
	movd		dword ptr [ DstPt + 0 ], xmm0
	add			SrcPt, 4
	add			DstPt, 4
	sub			SzByt, 4
	jmp			MemCpyAvxUpDstAlignOut
	MemCpyAvxUpDstAlign5:
	mov			r9b, byte ptr [ SrcPt + 0 ]
	mov			byte ptr [ DstPt + 0 ], r9b
	movd		xmm0, dword ptr [ SrcPt + 1 ]
	movd		dword ptr [ DstPt + 1 ], xmm0
	add			SrcPt, 5
	add			DstPt, 5
	sub			SzByt, 5
	jmp			MemCpyAvxUpDstAlignOut
	MemCpyAvxUpDstAlign6:
	mov			r9w, word ptr [ SrcPt + 0 ]
	mov			word ptr [ DstPt + 0 ], r9w
	movd		xmm0, dword ptr [ SrcPt + 2 ]
	movd		dword ptr [ DstPt + 2 ], xmm0
	add			SrcPt, 6
	add			DstPt, 6
	sub			SzByt, 6
	jmp			MemCpyAvxUpDstAlignOut
	MemCpyAvxUpDstAlign7:
	movd		xmm1, dword ptr [ SrcPt + 0 ]
	movd		xmm0, dword ptr [ SrcPt + 3 ]
	movd		dword ptr [ DstPt + 0 ], xmm1
	movd		dword ptr [ DstPt + 3 ], xmm0
	add			SrcPt, 7
	add			DstPt, 7
	sub			SzByt, 7
	jmp			MemCpyAvxUpDstAlignOut
