	align		64											; 64字节对齐。
	MemCpyAvxDown:											; Avx指令的从高到低地址复制。
	lea			SrcPt, [ SrcPt + SzByt ]					; 设置SrcPt为SrcPt+SzByt，也就是源始结束地址。
	lea			DstPt, [ DstPt + SzByt ]					; 设置DstPt为DstPt+SzByt，也就是目的结束地址。

	MemCpyAvxDownDstAlign:									; Avx指令的从高到低地址的目的地址32字节对齐复制。
	mov			r9, DstPt									; 设置r9为DstPt，也就是目的地址。
	and			r9, 31										; 设置r9为r9逻辑与31，也就是r9低5位。
	jz			MemCpyAvxDownDstAlignOut					; 如果r9低5位为0，表示目的地址已32字节对齐的，就跳转到开始复制。
